      "mainEntity": [
        {
          "@type": "Question",
          "name": "What is a RAG pipeline?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A system that retrieves external information and feeds it to a language model as context, grounding the response in real evidence."
          }
        },
        {
          "@type": "Question",
          "name": "What are the main steps in a RAG pipeline?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ingestion, chunking, embedding, indexing, retrieval, reranking, generation, and evaluation."
          }
        },
        {
          "@type": "Question",
          "name": "Does RAG eliminate hallucinations?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No — it lowers the risk by giving the model evidence to work from, but the model can still misread that context."
          }
        },
        {
          "@type": "Question",
          "name": "What's the difference between RAG and fine-tuning?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "RAG updates what a model can reference; fine-tuning updates behavior by retraining weights."
          }
        },
        {
          "@type": "Question",
          "name": "What is hybrid search in RAG?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Combining semantic vector search with keyword search so exact terms aren't missed."
          }
        },
        {
          "@type": "Question",
          "name": "How is a RAG pipeline evaluated?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "By scoring retrieval accuracy and generation faithfulness separately, using labeled queries with known sources."
          }
        },
